import{SCENES,layout}from'./core.mjs';
function rounded(ctx,x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r);}
export function demoImage(){const c=document.createElement('canvas');c.width=1200;c.height=1500;const x=c.getContext('2d');const g=x.createLinearGradient(0,0,1200,1500);g.addColorStop(0,'#ccd3bf');g.addColorStop(.5,'#8fa99c');g.addColorStop(1,'#26483e');x.fillStyle=g;x.fillRect(0,0,1200,1500);x.fillStyle='#e1d8ba';x.beginPath();x.arc(930,270,200,0,Math.PI*2);x.fill();x.fillStyle='#233f36';x.beginPath();x.moveTo(0,1500);x.lineTo(0,1110);x.lineTo(165,880);x.lineTo(320,1280);x.lineTo(480,1000);x.lineTo(820,1330);x.lineTo(1200,930);x.lineTo(1200,1500);x.fill();x.fillStyle='#b8c9ac88';for(let i=0;i<11;i++){x.beginPath();x.moveTo(i*150-150,0);x.bezierCurveTo(i*120+200,500,i*140-100,800,i*150+400,1500);x.lineWidth=2;x.strokeStyle='#d0dfca30';x.stroke();}const coat=x.createLinearGradient(100,800,1000,1450);coat.addColorStop(0,'#182f2d');coat.addColorStop(1,'#091d1d');x.fillStyle=coat;x.beginPath();x.moveTo(180,1500);x.bezierCurveTo(185,1200,260,950,445,900);x.lineTo(760,900);x.bezierCurveTo(960,960,1020,1210,1050,1500);x.closePath();x.fill();x.fillStyle='#d1a686';x.fillRect(510,725,180,230);x.fillStyle='#243931';x.beginPath();x.ellipse(600,525,233,310,-.08,0,Math.PI*2);x.fill();x.fillStyle='#d8b493';x.beginPath();x.ellipse(605,580,175,250,-.03,0,Math.PI*2);x.fill();x.fillStyle='#1c312c';x.beginPath();x.moveTo(401,590);x.bezierCurveTo(375,240,780,190,809,565);x.bezierCurveTo(745,425,610,420,525,390);x.bezierCurveTo(510,510,450,530,401,590);x.fill();x.fillStyle='#172d28';x.beginPath();x.moveTo(485,925);x.lineTo(600,1080);x.lineTo(690,925);x.lineTo(760,961);x.lineTo(675,1220);x.lineTo(540,1120);x.lineTo(410,971);x.fill();x.strokeStyle='#729184';x.lineWidth=3;x.beginPath();x.moveTo(600,1080);x.lineTo(650,1500);x.stroke();x.fillStyle='#9cae91';for(let y=1180;y<1480;y+=115){x.beginPath();x.arc(664,y,7,0,Math.PI*2);x.fill();}return c;}
export function drawMask(ctx,m,photo,scene){const x=photo.x+m.x*photo.w,y=photo.y+m.y*photo.h,rx=m.rx*photo.w*m.scale,ry=m.ry*photo.h*m.scale;ctx.save();ctx.translate(x,y);ctx.fillStyle='#f5f3e8';ctx.shadowColor='#00000026';ctx.shadowBlur=rx*.08;ctx.shadowOffsetY=ry*.025;
 if(m.style==='circle'){ctx.beginPath();ctx.ellipse(0,0,Math.max(rx,ry),Math.max(rx,ry),0,0,Math.PI*2);ctx.fill();}
 else if(m.style==='eyes'){rounded(ctx,-rx*1.05,-ry*.27,rx*2.1,ry*.63,rx*.05);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle=scene.dark;ctx.beginPath();ctx.ellipse(-rx*.4,0,rx*.19,ry*.09,0,0,Math.PI*2);ctx.ellipse(rx*.4,0,rx*.19,ry*.09,0,0,Math.PI*2);ctx.fill();}
 else if(m.style==='pixel'){ctx.shadowBlur=0;const colors=['#e6e8d8','#839883','#bcc9b3','#48675b'];const size=rx*.38;for(let iy=-3;iy<3;iy++)for(let ix=-3;ix<3;ix++){if(ix*ix+iy*iy>13)continue;ctx.fillStyle=colors[Math.abs(ix*3+iy*7)%colors.length];ctx.fillRect(ix*size,iy*size,size+1,size+1);}}
 else{ctx.beginPath();ctx.moveTo(-rx,-ry*.05);ctx.bezierCurveTo(-rx,-ry*1.35,rx,-ry*1.35,rx,-ry*.05);ctx.lineTo(rx,ry);ctx.quadraticCurveTo(rx*.76,ry*.64,rx*.52,ry);ctx.quadraticCurveTo(rx*.26,ry*.64,0,ry);ctx.quadraticCurveTo(-rx*.26,ry*.64,-rx*.52,ry);ctx.quadraticCurveTo(-rx*.76,ry*.64,-rx,ry);ctx.closePath();ctx.fill();ctx.shadowBlur=0;ctx.fillStyle=scene.dark;ctx.beginPath();ctx.ellipse(-rx*.34,-ry*.05,rx*.105,ry*.17,-.1,0,Math.PI*2);ctx.ellipse(rx*.34,-ry*.05,rx*.105,ry*.17,.1,0,Math.PI*2);ctx.fill();ctx.globalAlpha=.28;ctx.beginPath();ctx.ellipse(0,ry*.32,rx*.08,ry*.07,0,0,Math.PI*2);ctx.fill();}
 ctx.restore();}
function wrappedText(ctx,text,x,y,maxWidth,lineHeight,maxLines=2){let line='',lines=[];for(const ch of text){const next=line+ch;if(ctx.measureText(next).width>maxWidth&&line){lines.push(line);line=ch;}else line=next;}if(line)lines.push(line);lines.slice(0,maxLines).forEach((l,i)=>ctx.fillText(l,x,y+i*lineHeight));}
export function render(canvas,image,config,masks,{selected=-1,compare=false}={}){const l=layout(config,image);if(canvas.width!==l.w||canvas.height!==l.h){canvas.width=l.w;canvas.height=l.h;}const ctx=canvas.getContext('2d');ctx.save();ctx.clearRect(0,0,l.w,l.h);const s=SCENES[config.scene];if(config.format==='poster'){ctx.fillStyle=s.dark;ctx.fillRect(0,0,l.w,l.h);const g=ctx.createRadialGradient(l.w*.6,l.h*.43,0,l.w*.4,l.h*.5,l.h*.75);g.addColorStop(0,s.mid);g.addColorStop(1,s.dark);ctx.fillStyle=g;ctx.fillRect(0,0,l.w,l.h);ctx.globalAlpha=.17;ctx.strokeStyle=s.light;ctx.lineWidth=1;for(let i=0;i<20;i++){ctx.beginPath();ctx.moveTo(0,l.h*.1+i*l.h*.048);ctx.lineTo(l.w,l.h*.1+i*l.h*.048);ctx.stroke();}ctx.globalAlpha=1;}
ctx.drawImage(image,l.photo.x,l.photo.y,l.photo.w,l.photo.h);if(!compare){for(const m of masks)drawMask(ctx,m,l.photo,s);}
if(config.format==='poster'){const fade=ctx.createLinearGradient(0,l.h*.55,0,l.h*.82);fade.addColorStop(0,s.dark+'00');fade.addColorStop(1,s.dark);ctx.fillStyle=fade;ctx.fillRect(0,l.h*.55,l.w,l.h*.27);ctx.fillStyle=s.light;ctx.textAlign='center';ctx.font=`500 ${Math.round(l.w*.017)}px sans-serif`;ctx.letterSpacing=`${l.w*.004}px`;ctx.fillText('A  S T O R Y  A F T E R  D A R K',l.w*.5,l.h*.066);ctx.letterSpacing='0px';ctx.fillStyle=s.accent;ctx.font=`${l.w*.017}px sans-serif`;ctx.fillText('—   THE UNKNOWN   —',l.w*.5,l.h*.785);ctx.fillStyle=s.light;ctx.font=`500 ${l.w*.062}px "Songti SC", "Noto Serif CJK SC", serif`;let titleSize=l.w*.062;while(ctx.measureText(config.title).width>l.w*.86&&titleSize>l.w*.038){titleSize-=1;ctx.font=`500 ${titleSize}px "Songti SC", "Noto Serif CJK SC", serif`;}wrappedText(ctx,config.title,l.w*.5,l.h*.852,l.w*.86,l.w*.078,1);ctx.globalAlpha=.65;ctx.font=`${l.w*.020}px sans-serif`;wrappedText(ctx,config.subtitle,l.w*.5,l.h*.947,l.w*.83,l.w*.028,2);ctx.globalAlpha=1;}
if(selected>=0&&masks[selected]&&!compare){const m=masks[selected];ctx.strokeStyle='#ed9055';ctx.lineWidth=Math.max(2,l.w/450);ctx.setLineDash([l.w*.007,l.w*.004]);const x=l.photo.x+m.x*l.photo.w,y=l.photo.y+m.y*l.photo.h,rx=m.rx*l.photo.w*m.scale,ry=m.ry*l.photo.h*m.scale;ctx.strokeRect(x-rx*1.2,y-ry*1.2,rx*2.4,ry*2.4);ctx.setLineDash([]);}ctx.restore();return l;}
